{"code_completion":"module top_module (
	input in,
	input [3:0] state,
	output reg [3:0] next_state,
	output out
);

always @(*) begin
    next_state = 4'b0000;
    // State A: 4'b0001 (index 0)
    // State B: 4'b0010 (index 1)
    // State C: 4'b0100 (index 2)
    // State D: 4'b1000 (index 3)

    // A | A, B | 0
    // B | C, B | 0
    // C | A, D | 0
    // D | C, B | 1

    // next_state[A] = (state[A] & ~in) | (state[C] & ~in)
    // next_state[B] = (state[A] & in) | (state[B] & in) | (state[D] & in)
    // next_state[C] = (state[B] & ~in) | (state[D] & ~in)
    // next_state[D] = (state[C] & in)

    if (state[0]) begin
        if (!in) next_state[0] = 1'b1;
        else     next_state[1] = 1'b1;
    end else if (state[1]) begin
        if (!in) next_state[2] = 1'b1;
        else     next_state[1] = 1'b1;
    end else if (state[2]) begin
        if (!in) next_state[0] = 1'b1;
        else     next_state[3] = 1'b1;
    end else if (state[3]) begin
        if (!in) next_state[2] = 1'b1;
        else     next_state[1] = 1'b1;
    end
end

assign out = state[3];

endmodule
